    {'ll': [-75.1180, 40.1207], 'label': 'Abington, PA', 'date': 'Schempp, 1963', 'acc': True, 'big': True, 'anchor': 'start', 'dy': 20, 'plate': {'kicker': 'US7.13 · Bible reading', 'title': 'Abington v. Schempp', 'sub': '17 June 1963', 'text': "[[c-us7-relig-abington]]", 'sources': ['us7c-justia-abington', 'us7c-brit-abington']}},
